# Runs the burds Gradio app on a Kaggle GPU with a temporary public *.gradio.live link, for
# recording a demo video. The link is printed in the log and stays up for BURDS_HOURS hours.
import glob as _glob, os as _os, subprocess as _sp, sys as _sys  # noqa: E401
_sp.run([_sys.executable, "-m", "pip", "install", "-q", "-U", "gradio>=5", "sentence-transformers",
         "transformers", "librosa"], check=True)
_idx = _glob.glob("/kaggle/input/**/demo_index.npz", recursive=True)[0]
_os.environ["BURDS_DATA"] = _os.path.dirname(_idx)
_os.environ["BURDS_TAXA"] = [p for p in _glob.glob("/kaggle/input/**/taxa.csv", recursive=True) if "demo-data" in p][0]
_cfg = _glob.glob("/kaggle/input/**/embeddinggemma*/**/config.json", recursive=True)
if _cfg:
    _os.environ["BURDS_MODEL"] = _os.path.dirname(sorted(_cfg, key=len)[0])
_os.environ.setdefault("BURDS_SHARE", "1")
_os.environ.setdefault("BURDS_HOURS", "3")
